const NAMES: Readonly<Record<"windows" | "edge", string>> = {
    windows: "Windows",
    edge: "Microsoft Edge"
};

/** The official name of a mark, for its accessible label. */
export function markTitle(mark: MarkKey): string {
    return mark === "windows" || mark === "edge" ? NAMES[mark] : SIMPLE[mark].title;
}

