/** One mark, at the size its class gives it. Decorative unless titled: the
 *  name is always written beside it. */
export function PlatformMarkIcon({ mark, className }: { mark: MarkKey; className?: string }) {
    const common = { className, "aria-hidden": true, focusable: false } as const;
    if (mark === "edge") return <EdgeMark {...common} />;
    if (mark === "windows") {
        return (
            <svg viewBox="0 0 256 256" {...common}>
                <path
                    fill="#0078d4"
                    d="M0 0h121.329v121.329H0zm134.671 0H256v121.329H134.671zM0 134.671h121.329V256H0zm134.671 0H256V256H134.671z"
                />
            </svg>
        );
    }
    const one = SIMPLE[mark];
    return (
        <svg viewBox="0 0 24 24" {...common}>
            <path fill={one.color ?? "currentColor"} d={one.path} />
        </svg>
    );
}
